// Validate payload: first gate. Nothing downstream runs on a malformed request.
const t0 = Date.now();
const body = $input.first().json.body || {};
const bad = (code, message) => [{ json: { __invalid: true, ok: false, error: { code, message } } }];

if (body.source !== 'clara_growth_agent') return bad('INVALID_REQUEST', 'Unexpected source.');
if (!['analyze_prospect', 'record_decision'].includes(body.event)) return bad('INVALID_REQUEST', 'Unknown event.');
if (typeof body.company !== 'string' || !body.company.trim() || typeof body.leadId !== 'string') {
  return bad('INVALID_REQUEST', 'leadId and company are required.');
}
body.options = body.options || {};

const trace = [];
if (body.event === 'analyze_prospect') {
  trace.push({
    stage: 'received', event: 'Prospect received', status: 'ok', ts: new Date().toISOString(),
    detail: `${body.company} (${body.leadId}) received from Clara Growth Agent. Request ${body.requestId || 'n/a'}.`,
  });
}
return [{ json: { payload: body, trace, t0, startedAt: new Date(t0).toISOString() } }];

// Decision response: report what was (or was not) recorded in HubSpot.
const prev = $('Validate payload').first().json;
const payload = prev.payload;
const search = $('HubSpot: find company').first().json || {};
const company = Array.isArray(search.results) ? search.results[0] : null;
const fields = ['clara_human_decision', 'clara_workflow_route', 'clara_decision_at'];

let hubspot;
if (payload.options.writeback !== true) {
  hubspot = { attempted: false, updated: false, reason: 'Write-back disabled (HUBSPOT_WRITEBACK is not "true"): decision not written to HubSpot.' };
} else if (!company) {
  hubspot = { attempted: false, updated: false, reason: 'No HubSpot company found by name (or HubSpot unavailable): decision not written.' };
} else {
  let u = null;
  try { u = $('HubSpot: record decision').first().json; } catch (e) { u = null; }
  if (u && u.id && !u.error) hubspot = { attempted: true, updated: true, fields };
  else {
    const msg = u && (typeof u.error === 'string' ? u.error : (u.error && u.error.message) || u.message) || 'no response';
    hubspot = { attempted: true, updated: false, error: String(msg).slice(0, 250), reason: 'HubSpot rejected the update (are the clara_* properties created?).' };
  }
}
return [{ json: { ok: true, event: 'record_decision', finalRoute: payload.finalRoute, executionId: String($execution.id), hubspot } }];

// CRM context: interpret the HubSpot search (+ optional owner lookup).
// HubSpot being down or the company missing is NOT fatal: the workflow degrades,
// says so in the trace, and the routing rules cap the account at SDR Review.
const prev = $('Validate payload').first().json;
const payload = prev.payload;
const trace = [...prev.trace];
const ts = () => new Date().toISOString();

const search = $('HubSpot: find company').first().json || {};
let owner = null;
try {
  const o = $('HubSpot: get owner').first().json;
  if (o && o.id && !o.error) {
    owner = { id: String(o.id), name: [o.firstName, o.lastName].filter(Boolean).join(' ') || null, email: o.email || null };
  }
} catch (e) { /* owner node did not run: no owner assigned */ }

let crm;
if (search.error || !Array.isArray(search.results)) {
  const msg = typeof search.error === 'string' ? search.error : (search.error && search.error.message) || search.message || 'HubSpot request failed';
  crm = { source: 'hubspot', status: 'unavailable', found: false, error: String(msg).slice(0, 200) };
  trace.push({ stage: 'crm_context', event: 'HubSpot context unavailable', status: 'error', ts: ts(),
    detail: `${crm.error}. Continuing with payload data only; CRM status is unverified, so the account cannot reach AE Ready.` });
} else if (search.results.length === 0) {
  crm = { source: 'hubspot', status: 'not_found', found: false };
  trace.push({ stage: 'crm_context', event: 'HubSpot company not found', status: 'warn', ts: ts(),
    detail: `No HubSpot company named "${payload.company}". Import it first to enable CRM write-back; the account is capped at SDR Review until then.` });
} else {
  const c = search.results[0];
  const p = c.properties || {};
  crm = {
    source: 'hubspot', status: 'verified', found: true, companyId: String(c.id),
    lifecycleStage: p.lifecyclestage || null, leadStatus: p.hs_lead_status || null, owner,
    engagement: { contactedNotes: Number(p.num_contacted_notes || 0), lastContacted: p.notes_last_contacted || null },
  };
  trace.push({ stage: 'crm_context', event: 'HubSpot context retrieved', status: 'ok', ts: ts(),
    detail: `Company ${crm.companyId} found. Lifecycle: ${crm.lifecycleStage || 'not set'}. Owner: ${owner ? (owner.name || owner.id) : 'unassigned'}.` });
}
return [{ json: { payload, trace, crm, t0: prev.t0, startedAt: prev.startedAt } }];

// Deterministic ICP score. No LLM here: same inputs always give the same score,
// and every point is explained. Weights/thresholds come from the Clara UI
// ("Reglas de scoring"), already sanitised by the Netlify function.
const prev = $input.first().json;
const { payload, crm } = prev;
const trace = [...prev.trace];
const cfg = payload.scoringConfig;
const ts = () => new Date().toISOString();

// 1) Company size
const inRange = payload.employees >= cfg.tamano_min && payload.employees <= cfg.tamano_max;
const size = inRange
  ? { points: cfg.pesos.tamano, reason: `${payload.employees} employees, inside the ideal ${cfg.tamano_min}-${cfg.tamano_max} range` }
  : { points: 5, reason: `${payload.employees} employees, outside the ideal ${cfg.tamano_min}-${cfg.tamano_max} range` };

// 2) Payment/treasury pain (an agent HYPOTHESIS from public signals, not confirmed by the company)
const pain = (payload.painHypothesis || []).join(' ').toLowerCase();
const low = ['ya usa una plataforma de gasto corporativo', 'ya usa tarjetas corporativas'];
const high = ['manual', 'papel', 'sin tarjetas corporativas', 'sin consolidar', 'sin conciliación', 'sin tesorería centralizada'];
let painPts, painReason;
if (low.some(k => pain.includes(k))) { painPts = Math.round(cfg.pesos.dolor * 0.2); painReason = 'already uses a spend/treasury solution (low pain)'; }
else if (high.some(k => pain.includes(k))) { painPts = cfg.pesos.dolor; painReason = 'manual or unconsolidated payment/treasury processes (high pain, hypothesis)'; }
else { painPts = Math.round(cfg.pesos.dolor * 0.5); painReason = 'pain not classified, assumed medium'; }

// 3) Growth / buying signals (public facts)
const nSignals = (payload.signals || []).length;
const sigMax = cfg.pesos.senales * 3;
const sigPts = Math.min(nSignals * cfg.pesos.senales, sigMax);

const breakdown = [
  { factor: 'Company size', points: size.points, max: cfg.pesos.tamano, reason: size.reason },
  { factor: 'Payment pain (hypothesis)', points: painPts, max: cfg.pesos.dolor, reason: painReason },
  { factor: 'Growth signals', points: sigPts, max: sigMax, reason: `${nSignals} public signal(s), ${cfg.pesos.senales} pts each (cap 3)` },
];
const score = size.points + painPts + sigPts;
const qualified = score >= cfg.umbral_b;

// Context shown to the human but NOT scored (keeps this score identical to the one in the Clara dashboard).
const eng = crm.engagement && crm.engagement.contactedNotes > 0;
const context = [
  { label: 'Country', value: payload.country, note: 'not scored' },
  { label: 'Industry', value: payload.industry, note: 'not scored' },
  { label: 'CRM lifecycle stage', value: crm.lifecycleStage || (crm.status === 'verified' ? 'not set' : 'unknown'), note: 'used by routing rules' },
  { label: 'Prior engagement', value: eng ? `${crm.engagement.contactedNotes} contacted note(s)` : 'none recorded', note: 'used by routing rules' },
];

trace.push({ stage: 'scoring', event: 'ICP score calculated', status: 'ok', ts: ts(),
  detail: `${score}/100 = size ${size.points} + pain ${painPts} + signals ${sigPts}. Deterministic rules, no LLM.` });
trace.push({ stage: 'scoring', event: qualified ? 'Qualification threshold passed' : 'Below qualification threshold',
  status: qualified ? 'ok' : 'warn', ts: ts(),
  detail: `Score ${score} ${qualified ? '>=' : '<'} qualification threshold ${cfg.umbral_b}.` });

return [{ json: { payload, trace, crm, t0: prev.t0, startedAt: prev.startedAt,
  icp: { score, qualified, qualifyThreshold: cfg.umbral_b, highThreshold: cfg.umbral_a, breakdown, context } } }];

// Routing decision: deterministic rules + (optional) LLM interpretation.
// The LLM never decides the score or the route; it only explains and personalises.
const prev = $('Deterministic ICP score').first().json;
const { payload, crm, icp } = prev;
const cfg = payload.scoringConfig;
const trace = [...prev.trace];
const ts = () => new Date().toISOString();

// ---- LLM block (called only if the account passed the qualification gate) ----
let llm;
if (!icp.qualified) {
  llm = { status: 'skipped', skippedReason: 'Below qualification threshold: LLM not called (cost control).' };
  trace.push({ stage: 'ai_analysis', event: 'AI analysis skipped', status: 'skipped', ts: ts(), detail: llm.skippedReason });
} else {
  trace.push({ stage: 'ai_analysis', event: 'AI analysis requested', status: 'ok', ts: ts(),
    detail: 'Account qualified: asked the existing lead-reasoning endpoint for interpretation and an outreach angle.' });
  let r = null;
  try { r = $('LLM analysis').first().json; } catch (e) { r = null; }
  const rs = r && r.reasoning;
  if (rs && typeof rs === 'object' && (rs.resumen_calificacion || rs.razon_cuenta)) {
    const m = r.meta || {};
    llm = {
      status: 'ok',
      reason: rs.razon_cuenta || rs.resumen_calificacion,
      outreachAngle: rs.angulo_outreach || (rs.outreach && rs.outreach.asunto) || null,
      recommendedAction: rs.siguiente_mejor_accion || null,
      summary: rs.resumen_calificacion || null,
      subject: rs.outreach && rs.outreach.asunto || null,
      channel: rs.canal_recomendado || null, confidence: rs.confianza || null,
      model: m.model || null, estimatedCostUsd: m.estimated_cost_usd, totalTokens: m.total_tokens,
    };
    trace.push({ stage: 'ai_analysis', event: 'Recommendation generated', status: 'ok', ts: ts(),
      detail: `LLM (${llm.model || 'model n/a'}) returned reasoning and an outreach angle.` });
  } else {
    const msg = r && (typeof r.error === 'string' ? r.error : (r.error && r.error.message)) || 'no usable response';
    llm = { status: 'error', error: String(msg).slice(0, 200) };
    trace.push({ stage: 'ai_analysis', event: 'AI analysis failed', status: 'error', ts: ts(),
      detail: `${llm.error}. Routing continues on deterministic rules only; no AI text was generated.` });
  }
}

// ---- Deterministic routing rules ----
const rules = [];
let route, rationale, requiresApproval;
const stage = String(crm.lifecycleStage || '').toLowerCase();
const positive = (payload.signals || []).length + ((crm.engagement && crm.engagement.contactedNotes > 0) ? 1 : 0);

if (!icp.qualified) {
  route = 'NURTURE';
  rules.push(`Score ${icp.score} < qualification threshold ${cfg.umbral_b}`);
  rationale = 'Below the qualification threshold: no SDR time, no AI spend, stays in automated nurture.';
  requiresApproval = false;
} else {
  rules.push(`Score ${icp.score} >= qualification threshold ${cfg.umbral_b}`);
  route = 'SDR_REVIEW';
  if (icp.score >= cfg.umbral_a && positive >= 2) {
    route = 'AE_READY';
    rules.push(`Score >= ${cfg.umbral_a} and ${positive} positive signals (>=2)`);
  } else if (icp.score >= cfg.umbral_a) {
    rules.push(`Score >= ${cfg.umbral_a} but only ${positive} positive signal(s) (<2): SDR validates first`);
  } else {
    rules.push(`Score < high-fit threshold ${cfg.umbral_a}: SDR validates first`);
  }
  if (route === 'AE_READY' && (crm.status === 'not_found' || crm.status === 'unavailable')) {
    route = 'SDR_REVIEW';
    rules.push(`CRM status "${crm.status}": cannot hand off to AE without a verified HubSpot record`);
  }
  if (route === 'AE_READY' && (stage === 'customer' || stage === 'evangelist')) {
    route = 'SDR_REVIEW';
    rules.push(`Lifecycle stage "${stage}": existing customer, owner reviews instead of AE outbound`);
  }
  rationale = route === 'AE_READY'
    ? 'High ICP fit, multiple positive signals and a verified CRM record: ready for AE handoff once a human approves.'
    : 'Qualified, but an SDR must validate the account before any outbound.';
  requiresApproval = true;
}

const defaults = {
  NURTURE: 'Keep in automated nurture; no outbound.',
  SDR_REVIEW: 'SDR reviews the account and decides whether to approve an outbound sequence.',
  AE_READY: 'Hand off to an AE and book a discovery call once approved.',
};
const recommendedAction = (llm.status === 'ok' && llm.recommendedAction) ? llm.recommendedAction : defaults[route];

trace.push({ stage: 'routing', event: 'Routing decision', status: 'ok', ts: ts(), detail: `${route}. ${rules.join('; ')}.` });

return [{ json: { payload, trace, crm, icp, llm, t0: prev.t0, startedAt: prev.startedAt,
  routing: { route, rationale, rulesFired: rules, requiresApproval, recommendedAction } } }];

// Build response: the contract the Clara UI renders. HubSpot write-back outcome is reported honestly.
const prev = $('Routing decision').first().json;
const { payload, crm, icp, llm, routing } = prev;
const trace = [...prev.trace];
const ts = () => new Date().toISOString();

const fields = ['clara_ai_score', 'clara_qualification_status', 'clara_ai_recommendation', 'clara_next_action', 'clara_workflow_route', 'clara_last_analyzed_at'];
let writeback;
if (!(payload.options && payload.options.writeback === true)) {
  writeback = { attempted: false, updated: false, reason: 'Write-back disabled (HUBSPOT_WRITEBACK is not "true"): HubSpot was only read.' };
  trace.push({ stage: 'crm_update', event: 'HubSpot update skipped', status: 'skipped', ts: ts(), detail: writeback.reason });
} else if (!crm.found) {
  writeback = { attempted: false, updated: false, reason: `No verified HubSpot company (status: ${crm.status}).` };
  trace.push({ stage: 'crm_update', event: 'HubSpot update skipped', status: 'skipped', ts: ts(), detail: writeback.reason });
} else {
  let u = null;
  try { u = $('HubSpot: update AI fields').first().json; } catch (e) { u = null; }
  if (u && u.id && !u.error) {
    writeback = { attempted: true, updated: true, fields };
    trace.push({ stage: 'crm_update', event: 'HubSpot updated', status: 'ok', ts: ts(), detail: `Wrote ${fields.length} AI properties to company ${crm.companyId}.` });
  } else {
    const msg = u && (typeof u.error === 'string' ? u.error : (u.error && u.error.message) || u.message) || 'no response';
    writeback = { attempted: true, updated: false, error: String(msg).slice(0, 250),
      reason: 'The update was attempted but HubSpot rejected it. Most likely the custom clara_* properties do not exist yet.' };
    trace.push({ stage: 'crm_update', event: 'HubSpot update failed', status: 'error', ts: ts(), detail: writeback.error });
  }
}
if (routing.requiresApproval) {
  trace.push({ stage: 'approval', event: 'Human approval requested', status: 'pending', ts: ts(),
    detail: `Waiting for a human to approve the ${routing.route} recommendation. Nothing is sent without it.` });
}
trace.push({ stage: 'completed', event: 'Workflow completed', status: 'ok', ts: ts(), detail: `Route: ${routing.route}.` });

return [{ json: {
  ok: true, event: 'analyze_prospect',
  icp, crm: { ...crm, writeback }, llm, routing, trace,
  execution: { id: String($execution.id), durationMs: Date.now() - prev.t0, startedAt: prev.startedAt, finishedAt: new Date().toISOString(), workflow: 'Clara Growth Agent - n8n orchestration' },
} }];
